from pathlib import Path
p=Path('output/miner-mockup/build_revised.py'); s=p.read_text(encoding='utf-8-sig')
a='Competition from established equipment providers will require demonstrated performance. We expect buyer bargaining power to be high because mining customers are often large conglomerates whose adoption decisions must account for miners and unions. We expect supplier bargaining power to be relatively low: we plan to source most sensors and mechanical materials from China and compare multiple suppliers, subject to quality and compatibility checks. New entrants can buy standard components, but reliable integration and field validation remain barriers. Manual crews and remotely operated equipment are substitutes. The pilot must demonstrate reliable exploration and mapping, acceptable sample quality and lower total operating costs.'
b='Established equipment providers create competition. We expect buyer bargaining power to be high because mining corporations are often large conglomerates and must account for miners and unions. Supplier bargaining power is expected to be relatively low: we plan to source most sensors and mechanical materials from multiple suppliers in China, subject to qualification. Standard components enable entry, while integration and field testing remain barriers. Manual crews and remotely operated equipment are substitutes. The pilot must demonstrate reliable exploration, mapping and sampling at lower total cost.'
assert a in s
p.write_text(s.replace(a,b),encoding='utf-8')
